{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Santa Ana Rent Stabilization Ordinance annual rent cap","requirement":"A landlord may not raise residential rent by more than the lower of 3% per year or 80% of the 12-month change in the Consumer Price Index; no increase is allowed when the CPI is negative.","key_value":"Lower of 3% per year or 80% of CPI change; none if CPI negative","coverage_conditions":"Residential rentals in Santa Ana, but not residential buildings constructed after February 1, 1995, or mobile home spaces offered for rent after January 1, 1990.","applicability":{"conditions":[{"type":"built","role":"exempt","op":"after","date":"1995-02-01","basis":"construction"}],"per_tenancy":null,"coverage_quotes":["The rent cap does not apply to residential buildings constructed after February 1, 1995, or to mobile home spaces offered for rent after January 1, 1990."]},"exemptions":"Residential buildings constructed after February 1, 1995; mobile home spaces offered for rent after January 1, 1990.","penalty":null,"effective_date":"2021-11-19","valid_through":null,"citation":"Santa Ana Rent Stabilization Ordinance","quoted_span":"Increase in residential rents are limited to the lower of 3% per year, or 80% of the percent change in the Consumer Price Index over the most recent 12-month period. If the CPI is negative, no rent increase is permitted.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Santa Ana Just Cause Eviction Ordinance","requirement":"After 30 days of tenancy, a landlord may not terminate a tenancy without just cause stated in a written notice, and for a no-fault termination must give 3 months' relocation assistance or waive the final 3 months' rent.","key_value":"Just cause required after 30 days; 3 months' relocation assistance","coverage_conditions":"Residential rentals in Santa Ana, except housing produced in the last 15 years, deed-restricted affordable housing, hotels and transient occupancy, hospital and care facilities, dormitories and other shared living quarters.","applicability":{"conditions":[{"type":"built_within_years","role":"exempt","years":15,"basis":"construction"},{"type":"other","role":"exempt","text":"deed-restricted affordable housing"}],"per_tenancy":"Just cause protections begin after 30 days of tenancy.","coverage_quotes":["After 30 days, an owner shall not terminate a tenancy without just cause, which shall be stated in a written notice.","The Just Cause Ordinance shall not apply to certain types of residential property, including housing produced in the last 15 years; deed-restricted affordable housing; hotel and transient occupancy; hospital and care facilities; dormitories; and other shared living quarters."]},"exemptions":"Housing produced in the last 15 years; deed-restricted affordable housing; hotel and transient occupancy; hospital and care facilities; dormitories; and other shared living quarters.","penalty":null,"effective_date":"2021-11-19","valid_through":null,"citation":"Santa Ana Just Cause Eviction Ordinance","quoted_span":"After 30 days, an owner shall not terminate a tenancy without just cause, which shall be stated in a written notice.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D085-01","n_rules":2,"note":null}

